window.__code__["code-w01-concurrent-providers-py"] = {"code_id": "code-w01-concurrent-providers-py", "kind": "local", "title": "concurrent_providers.py", "source_path": "/Users/zhongyou/Desktop/2027年/code/w01/concurrent_providers.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># code/w01/concurrent_providers.py</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-com\"># W01 作业2:并发调多个模型,用 asyncio.gather 对比串行</span></span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\"><span class=\"c-com\"># 体会:IO 密集用异步,gather 让总耗时≈最慢的那个(而非三者之和)</span></span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-com\"># 前置: export DASHSCOPE_API_KEY=\u00004\u0000</span></span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-com\"># 运行:  python code/w01/concurrent_providers.py</span></span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-com\"># 预期:  三行几乎同时打印(并发),总耗时≈单次最慢者。</span></span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-com\">#        把下面 gather 换成顺序 await,总耗时会变成三者之和——对照体验</span></span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-kw\">import</span> asyncio</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\"><span class=\"c-kw\">import</span> os</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\"><span class=\"c-kw\">import</span> time</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\"><span class=\"c-kw\">import</span> httpx</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">URL = <span class=\"c-str\">&quot;https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\"><span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> call_once(label: str, model: str, prompt: str) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">    headers = {<span class=\"c-str\">&quot;Authorization&quot;</span>: f<span class=\"c-str\">&quot;Bearer {os.environ[&#x27;DASHSCOPE_API_KEY&#x27;]}&quot;</span>}</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">    payload = {<span class=\"c-str\">&quot;model&quot;</span>: model, <span class=\"c-str\">&quot;messages&quot;</span>: [{<span class=\"c-str\">&quot;role&quot;</span>: <span class=\"c-str\">&quot;user&quot;</span>, <span class=\"c-str\">&quot;content&quot;</span>: prompt}]}</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">    t0 = time.perf_counter()</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">with</span> httpx.AsyncClient(timeout=60) <span class=\"c-kw\">as</span> client:</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">        r = <span class=\"c-kw\">await</span> client.post(URL, headers=headers, json=payload)</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">        r.raise_for_status()</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">        text = r.json()[<span class=\"c-str\">&quot;choices&quot;</span>][0][<span class=\"c-str\">&quot;message&quot;</span>][<span class=\"c-str\">&quot;content&quot;</span>]</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">    dt = time.perf_counter() - t0</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">    print(f<span class=\"c-str\">&quot;[{label}] {dt:.2f}s -&gt; {text[:40]}&quot;</span>, flush=<span class=\"c-kw\">True</span>)</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> text</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\"><span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> main() -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">    prompt = <span class=\"c-str\">&quot;一句话回答:1+1 等于几?&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">    print(<span class=\"c-str\">&quot;--- 并发版本(asyncio.gather) ---&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">    t0 = time.perf_counter()</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">    <span class=\"c-com\"># 三个协程并发,总耗时 ≈ max(三者),不是三者之和</span></span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">    <span class=\"c-kw\">await</span> asyncio.gather(</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">        call_once(<span class=\"c-str\">&quot;qwen-plus-a&quot;</span>, <span class=\"c-str\">&quot;qwen-plus&quot;</span>, prompt),</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">        call_once(<span class=\"c-str\">&quot;qwen-turbo&quot;</span>, <span class=\"c-str\">&quot;qwen-turbo&quot;</span>, prompt),</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">        call_once(<span class=\"c-str\">&quot;qwen-plus-b&quot;</span>, <span class=\"c-str\">&quot;qwen-plus&quot;</span>, prompt),</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">    print(f<span class=\"c-str\">&quot;并发总耗时: {time.perf_counter() - t0:.2f}s&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">    <span class=\"c-com\"># 对照:把上面 gather 改成下面顺序 await,看总耗时变成三者之和</span></span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">    <span class=\"c-com\"># print(\u000033\u0000)</span></span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">    <span class=\"c-com\"># t0 = time.perf_counter()</span></span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">    <span class=\"c-com\"># await call_once(\u000036\u0000, \u000037\u0000, prompt)</span></span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">    <span class=\"c-com\"># await call_once(\u000039\u0000, \u000040\u0000, prompt)</span></span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">    <span class=\"c-com\"># await call_once(\u000042\u0000, \u000043\u0000, prompt)</span></span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">    <span class=\"c-com\"># print(f\u000045\u0000)</span></span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\"><span class=\"c-kw\">if</span> __name__ == <span class=\"c-str\">&quot;__main__&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">    asyncio.run(main())</span></div>\n</div>", "lines": 54, "explanation": "concurrent_providers.py 是本教程的可运行示例代码，示范对应周次核心概念；顶部注释含运行前置依赖与预期输出，建议结合左侧源码与对应周文档「动手作业」一起读。", "knowledge_points": [], "related_docs": ["W01-Python异步与LLM-API调用"]};
